```java
import java.util.*;

class Solution {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String entrada = in.nextLine();
        String[] placas = entrada.split(",\\s*"); // Adiciona suporte para espaços após vírgula

        final int ultimoIndice = 7;
        final int indexHifen = 3;

        // Implementação do Radix Sort
        for (int indice = ultimoIndice; indice > indexHifen; indice--)
            placas = countingSort(placas, indice);

        // Construção da saída formatada corretamente
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < placas.length; i++) {
            out.append(placas[i]);
            if (i < placas.length - 1) {
                out.append(", ");
            }
        }

        System.out.println(out.toString());
    }

    private static String[] countingSort(String[] v, int index) {
        int[] c = new int[10];
        for (String placa : v) {
