import java.util.*;

class BST {
    private Node root;

    public BST() {
        this.root = null;
    }

    public void add(int value) {
        if (root == null) {
            root = new Node(value);
        } else {
            root.add(value);
        }
    }

    public void preOrder(ArrayList<Integer> list) {
        if (root != null) {
            root.preOrder(list);
        }
    }

    public int findClosest(int target) {
        if (root == null) {
            throw new RuntimeException("Empty tree");
        }

        Node current = root;
        int closest = root.value;
        int minDiff = Math.abs(target - closest);

        while (current != null) {
            int currentDiff = Math.abs(target - current.value);
            if (currentDiff < minDiff) {
                minDiff = currentDiff;
                closest = current.value;
            }

            if (target < current.value) {
                current = current.left;
            } else if (target > current.value) {
                current = current.right;
            } else {
                return current.value;
            }
        }
        return closest;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        BST tree = new BST();

        // Read input values
        String[] values = scanner.nextLine().split(" ");
        for (String val : values) {
            tree.add(Integer.parseInt(val));
        }

        // Read target value
        int target = scanner.nextInt();

