```java
import java.util.Arrays;
import java.util.Scanner;

public class RadixSortTresDigitos {

    public static int[] countingSort(int[] array, int maxValue, int digitGroup) {
        int[] count = new int[maxValue + 1];
        int[] output = new int[array.length];

        // Contagem da frequência dos números no grupo de dígitos atual
        for (int num : array) {
            int currentGroup = extractDigitGroup(num, digitGroup);
            count[currentGroup]++;
        }

        // Cálculo da posição cumulativa
        for (int i = 1; i <= maxValue; i++) {
            count[i] += count[i - 1];
        }

        // Construção do array de saída
        for (int i = array.length - 1; i >= 0; i--) {
            int currentGroup = extractDigitGroup(array[i], digitGroup);
            output[count[currentGroup] - 1] = array[i];
            count[currentGroup]--;
        }

        return output;
    }

    public static int extractDigitGroup(int number, int digitGroup) {
        // Extrai o trio de dígitos atual (1-3, 4-6, etc.)
        int divisor = (int) Math.pow(10, digitGroup - 1);
        int modulo = (int) Math.pow(10, digitGroup + 2);
        return (number % modulo) / divisor;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] input = scanner.nextLine().split(" ");
        int[] numbers = new int[input.length];
