import java.util.Scanner;

class Node {
    int value;
    Node next;
    Node prev;

    Node(int value) {
        this.value = value;
        this.next = null;
        this.prev = null;
    }
}

class Queue {
    private Node front;
    private Node rear;
    private int size;

    public Queue() {
        this.front = null;
        this.rear = null;
        this.size = 0;
    }

    public boolean isEmpty() {
        return this.front == null;
    }

    public void add(int value) {
        Node newNode = new Node(value);
        if (isEmpty()) {
            front = rear = newNode;
        } else {
            rear.next = newNode;
            newNode.prev = rear;
            rear = newNode;
        }
        size++;
    }

    public int remove() {
        if (isEmpty()) {
            return -1; // Indicates empty queue
        }
        int value = front.value;
        front = front.next;
        if (front == null) {
            rear = null;
        } else {
            front.prev = null;
        }
        size--;
        return value;
    }

    public int element() {
        if (isEmpty()) {
            return -1;
        }
        return front.value;
    }

    public int search(int value) {
        return searchRecursive(front, value, 0);
    }

    private int searchRecursive(Node current, int value, int index) {
        if (current == null) {
            return -1;
        }
        if (current.value == value) {
            return index;
        }
        return searchRecursive(current.next, value, index + 1);
    }

    public String print() {
        if (isEmpty()) {
            return "empty";
        }
        return printRecursive(front, "");
    }

    private String printRecursive(Node current, String result) {
        if (current == null) {
            return result.trim();
        }
        return printRecursive(current.next, result + current.value + " ");
    }
}

public class Solution {
