                    System.out.println(queue.print());
                    break;
                case "element":
                    int elem = queue.element();
                    System.out.println(elem == -1 ? "empty" : elem);
                    break;
                case "remove":
                    int removed = queue.remove();
                    if (removed == -1) {
                        System.out.println("empty");
                    }
                    break;
                default:
                    if (op.startsWith("add ")) {
                        int value = Integer.parseInt(op.substring(4));
                        queue.add(value);
                    } else if (op.startsWith("search ")) {
                        int value = Integer.parseInt(op.substring(7));
                        System.out.println(queue.search(value));
                    }
                    break;
            }
        }
    }
}
