        return heightRec(root);
    }

    private int heightRec(Node node) {
        if (node == null)
            return -1;
        else {
            int leftHeight = heightRec(node.left);
            int rightHeight = heightRec(node.right);

            return Math.max(leftHeight, rightHeight) + 1;
        }
    }
}

